import cpmpy as cp
import json

# Data
n = 9  # Order of the Steiner Triple System
num_triples = n * (n - 1) // 6

# Model definition
model = cp.Model()

# Decision Variables
# x[i][j][k] is 1 if the triple (i, j, k) is included, 0 otherwise
x = cp.intvar(0, 1, shape=(n, n, n), name="x")

# Constraints
# Each triple (i, j, k) should be in the set only once and in sorted order (i < j < k)
for i in range(n):
    for j in range(i + 1, n):
        for k in range(j + 1, n):
            model += x[i, j, k] == cp.sum([x[i, j, k], x[i, k, j], x[j, i, k], x[j, k, i], x[k, i, j], x[k, j, i]])

# Each element appears in exactly (n-1)/2 triples
for i in range(n):
    model += cp.sum([x[i, j, k] for j in range(n) for k in range(n) if i < j < k]) == (n - 1) // 2

# Any two elements appear together in exactly one triple
for i in range(n):
    for j in range(i + 1, n):
        model += cp.sum([x[i, j, k] for k in range(n) if k != i and k != j]) == 1

# Objective (none needed for this problem)

# Solve and print
if model.solve():
    sets = []
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if x[i, j, k].value() == 1:
                    sets.append([i + 1, j + 1, k + 1])  # Adding 1 to convert from 0-based to 1-based index
    solution = {'sets': sets}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

