import json
import numpy as np

# Data
n = 5

# Model definition
model = cp.Model()

# Decision Variables
x = cp.intvar(1, n*n, shape=(n, n), name="x")

# Constraints
# Each number from 1 to n*n must appear exactly once
model += cp.AllDifferent(x)

# Helper function to add movement constraints
def add_movement_constraints(model, x, n):
    for i in range(n):
        for j in range(n):
            current = x[i, j]
            # Check all possible movements
            # Vertical and Horizontal movements
            if i + 3 < n:
                model += (current + 1 == x[i + 3, j]) | (current - 1 == x[i + 3, j])
            if i - 3 >= 0:
                model += (current + 1 == x[i - 3, j]) | (current - 1 == x[i - 3, j])
            if j + 3 < n:
                model += (current + 1 == x[i, j + 3]) | (current - 1 == x[i, j + 3])
            if j - 3 >= 0:
                model += (current + 1 == x[i, j - 3]) | (current - 1 == x[i, j - 3])

            # Diagonal movements
            if i + 2 < n and j + 2 < n:
                model += (current + 1 == x[i + 2, j + 2]) | (current - 1 == x[i + 2, j + 2])
            if i + 2 < n and j - 2 >= 0:
                model += (current + 1 == x[i + 2, j - 2]) | (current - 1 == x[i + 2, j - 2])
            if i - 2 >= 0 and j + 2 < n:
                model += (current + 1 == x[i - 2, j + 2]) | (current - 1 == x[i - 2, j + 2])
            if i - 2 >= 0 and j - 2 >= 0:
                model += (current + 1 == x[i - 2, j - 2]) | (current - 1 == x[i - 2, j - 2])

add_movement_constraints(model, x, n)

# Solve and print
if model.solve():
    solution = {'x': x.value().tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

This code sets up a CPMpy model to solve the problem of filling an n by n grid with numbers from 1 to n^2, following the specified movement rules. The solution is printed in JSON format with the completed grid as the value for the key 'x'.

